<?php
declare(strict_types=1);require_once __DIR__.'/includes/store.php';
$pageTitle='Home';
$products=$pdo->query("SELECT p.*,c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.is_active=1 AND p.is_featured=1 ORDER BY p.created_at DESC LIMIT 20")->fetchAll();
$latest=$pdo->query("SELECT * FROM products WHERE is_active=1 ORDER BY created_at DESC LIMIT 20")->fetchAll();
$homeCategories=[];try{$homeCategories=$pdo->query("SELECT id,name,slug FROM categories WHERE is_active=1 AND show_on_home=1 ORDER BY name")->fetchAll();}catch(Throwable $e){}
$categorySections=[];foreach($homeCategories as $c){$st=$pdo->prepare('SELECT * FROM products WHERE is_active=1 AND category_id=? ORDER BY is_featured DESC,created_at DESC LIMIT 20');$st->execute([(int)$c['id']]);$items=$st->fetchAll();if($items)$categorySections[]=['category'=>$c,'products'=>$items];}
$slides=json_decode(setting('homepage_slides','[]'),true)?:[];if(!$slides)$slides=[['title'=>'Technology that fits your life','subtitle'=>'Discover dependable electronics, smart accessories and everyday essentials.','button'=>'Shop now','url'=>'shop.php','image'=>'']];
require __DIR__.'/includes/header.php';
?>
<section class="home-hero-slider" data-slider>
 <?php foreach($slides as $i=>$slide):?><article class="hero-slide <?=$i===0?'active':''?>" style="<?php if(!empty($slide['image'])):?>background-image:linear-gradient(90deg,rgba(5,10,22,.78),rgba(5,10,22,.15)),url('<?=e($slide['image'])?>');<?php endif;?>"><div class="container hero-slide-content"><span class="eyebrow text-white">BLUECIRCUIT ELECTRONICS</span><h1><?=e($slide['title']??'Shop smarter')?></h1><p><?=e($slide['subtitle']??'Find the right technology for your everyday needs.')?></p><div class="d-flex gap-2 flex-wrap"><a class="btn btn-primary btn-lg" href="<?=e($slide['url']??'shop.php')?>"><?=e($slide['button']??'Shop now')?> <i class="bi bi-arrow-right"></i></a><?php if(setting('whatsapp_number','')):?><a class="btn btn-outline-light btn-lg" href="https://wa.me/<?=e(preg_replace('/\\D+/','',setting('whatsapp_number','')))?>" target="_blank" rel="noopener"><i class="bi bi-whatsapp"></i> WhatsApp</a><?php endif;?></div></div></article><?php endforeach;?>
 <?php if(count($slides)>1):?><button class="hero-arrow prev" data-slide-prev aria-label="Previous slide"><i class="bi bi-chevron-left"></i></button><button class="hero-arrow next" data-slide-next aria-label="Next slide"><i class="bi bi-chevron-right"></i></button><div class="hero-dots"><?php foreach($slides as $i=>$slide):?><button data-slide-dot="<?=$i?>" class="<?=$i===0?'active':''?>" aria-label="Go to slide <?=$i+1?>"></button><?php endforeach;?></div><?php endif;?>
</section>
