function product_rail(string $title,array $items,string $allUrl='shop.php'):void{if(!$items)return;?><section class="container py-4 product-rail-section"><div class="rail-heading"><h2><?=e($title)?></h2><div class="d-flex align-items-center gap-3"><a href="<?=e($allUrl)?>">View All</a><button class="rail-arrow" data-rail-prev aria-label="Previous products"><i class="bi bi-chevron-left"></i></button><button class="rail-arrow" data-rail-next aria-label="Next products"><i class="bi bi-chevron-right"></i></button></div></div><div class="product-rail" data-product-rail><?php foreach($items as $product):?><div class="product-rail-item"><?php require __DIR__.'/includes/product-card.php';?></div><?php endforeach;?></div></section><?php }
product_rail('Featured Products',$products);foreach($categorySections as $section)product_rail($section['category']['name'],$section['products'],'shop.php?category='.(int)$section['category']['id']);product_rail('New Arrivals',$latest);
?>
